def run(args, log=None, expected=0, timeout=300, input=None):
    start = time.monotonic()
    p = subprocess.run([str(x) for x in args], capture_output=True, text=True, env=env, timeout=timeout, input=input)
    text = p.stdout+p.stderr
    if log: (A/'evidence/gen'/log).write_text('# '+H+'\n'+normalize(text))
    if expected is not None and p.returncode != expected:
        print(normalize(text[-8000:]))
        raise RuntimeError(f'Unexpected exit {p.returncode} for {args[:3]}')
    return p, text, time.monotonic()-start

