def archive(commit, destination):
    if destination.exists():
        for p in destination.rglob('*'):
            if not p.is_symlink(): p.chmod(p.stat().st_mode | 0o200)
        shutil.rmtree(destination)
    destination.mkdir(parents=True)
    data = subprocess.check_output(['git', '-C', 'published/swift-asn1-git', 'archive', commit], env=env)
    with tarfile.open(fileobj=io.BytesIO(data)) as tf: tf.extractall(destination, filter='data')

