def swift(package, scratch, build=False, configuration='debug', command='test'):
    args = ['swift', command, '--package-path', str(package), '--scratch-path', str(ROOT/scratch), '--cache-path', str(ROOT/'.swiftpm-cache'), '--disable-sandbox', '-c', configuration]
